// CONFIG is generated by build.py from the exact published files.
const BASE = new URL('./', self.location.href);
const PREFIX = `shnotes:${BASE.pathname}:`;
const SHELL = `${PREFIX}shell:${CONFIG.revision}`;
const ENGINE = `${PREFIX}engine:${CONFIG.engineRevision}`;
const DOCS = `${PREFIX}documents`;
const META = `${PREFIX}saved`;
const urlOf = path => new URL(path, BASE).href;

self.addEventListener('install', event => event.waitUntil((async () => {
  const cache = await caches.open(SHELL);
  await cache.addAll(CONFIG.core.map(urlOf));
  // Existing offline lectures must keep a complete reader after a site update.
  if ((await (await caches.open(META)).keys()).length) await (await caches.open(ENGINE)).addAll(CONFIG.assets.map(urlOf));
})()));
self.addEventListener('activate', event => event.waitUntil((async () => {
  for (const key of await caches.keys()) {
    if ((key.startsWith(`${PREFIX}shell:`) && key !== SHELL) || (key.startsWith(`${PREFIX}engine:`) && key !== ENGINE)) await caches.delete(key);
  }
  await self.clients.claim();
})()));

async function rangeResponse(request, response) {
  const range = request.headers.get('range');
  if (!range) return response;
  const buffer = await response.arrayBuffer(), length = buffer.byteLength;
  const match = range.match(/^bytes=(\d*)-(\d*)$/);
  if (!match || (!match[1] && !match[2])) return new Response(null, {status: 416, headers: {'Content-Range': `bytes */${length}`}});
  const start = match[1] ? Number(match[1]) : Math.max(0, length - Number(match[2]));
  const end = match[1] && match[2] ? Math.min(length - 1, Number(match[2])) : length - 1;
  if (start > end || start >= length) return new Response(null, {status: 416, headers: {'Content-Range': `bytes */${length}`}});
  return new Response(buffer.slice(start, end + 1), {status: 206, headers: {
    'Content-Type': 'application/pdf', 'Content-Range': `bytes ${start}-${end}/${length}`,
    'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes'
  }});
}

self.addEventListener('fetch', event => {
  const request = event.request, url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== BASE.origin || !url.pathname.startsWith(BASE.pathname)) return;
  event.respondWith((async () => {
    const shell = await caches.open(SHELL);
    if (request.mode === 'navigate') {
      try {return await fetch(request)} catch {return (await shell.match(urlOf('index.html'))) || Response.error()}
    }
    const saved = await (await caches.open(DOCS)).match(request);
    if (saved) return rangeResponse(request, saved);
    const cached = await shell.match(request);
    return cached || (await (await caches.open(ENGINE)).match(request)) || fetch(request);
  })());
});

let saving = Promise.resolve();
async function command(data, reply) {
  const meta = await caches.open(META), docs = await caches.open(DOCS);
  const key = id => urlOf(`offline-meta/${encodeURIComponent(id)}`);
  if (data.type === 'list') {
    const records = await Promise.all((await meta.keys()).map(async request => (await meta.match(request)).json()));
    const existing = [];
    for (const record of records) if (await docs.match(record.file)) existing.push(record);
    return existing;
  }
  if (!/^[a-z0-9-]+$/.test(data.item?.id || data.id || '')) throw Error('Неверный конспект.');
  if (data.type === 'remove') {
    const response = await meta.match(key(data.id));
    if (response) {await docs.delete((await response.json()).file); await meta.delete(key(data.id))}
    if (!(await meta.keys()).length) await caches.delete(ENGINE);
    return true;
  }
  if (data.type !== 'save') throw Error('Неизвестное действие.');
  const item = data.item, file = new URL(item.file, BASE);
  if (file.origin !== BASE.origin || !file.pathname.startsWith(BASE.pathname) || !file.pathname.toLowerCase().endsWith('.pdf')) throw Error('Неверный адрес PDF.');
  const engine = await caches.open(ENGINE);
  const assets = CONFIG.assets.map(urlOf);
  let done = 0;
  // A handful of requests at a time avoids flooding a phone's connection.
  async function assetWorker() {
    while (assets.length) {
      const url = assets.pop();
      if (!await engine.match(url)) {
        const response = await fetch(url);
        if (!response.ok) throw Error('Не удалось сохранить читалку. Проверьте соединение.');
        await engine.put(url, response);
      }
      reply({progress: {done: ++done, total: CONFIG.assets.length + 1}});
    }
  }
  const downloads = await Promise.allSettled(Array.from({length: 4}, assetWorker));
  const failed = downloads.find(result => result.status === 'rejected');
  if (failed) throw failed.reason;
  const response = await fetch(file, {cache: 'reload'});
  if (!response.ok || response.status !== 200) throw Error('Не удалось сохранить PDF. Проверьте соединение.');
  // Read the full body before declaring this lecture available offline.
  const bytes = await response.arrayBuffer();
  const previous = await meta.match(key(item.id));
  await docs.put(file.href, new Response(bytes, {headers: {'Content-Type': 'application/pdf', 'Content-Length': String(bytes.byteLength)}}));
  const record = {id: item.id, title: item.title, lecture: item, file: file.href, size: bytes.byteLength, savedAt: Date.now(), revision: CONFIG.revision};
  await meta.put(key(item.id), new Response(JSON.stringify(record), {headers: {'Content-Type': 'application/json'}}));
  if (previous) {const old = await previous.json(); if (old.file !== file.href) await docs.delete(old.file)}
  reply({progress: {done: CONFIG.assets.length + 1, total: CONFIG.assets.length + 1}});
  return record;
}
self.addEventListener('message', event => {
  const reply = value => event.ports[0]?.postMessage(value);
  // Serialize saves/removals so rapid repeated taps cannot corrupt metadata.
  saving = saving.catch(() => {}).then(() => command(event.data, reply));
  event.waitUntil(saving.then(result => reply({result}), error => reply({error:
    error.name === 'QuotaExceededError' ? 'Недостаточно места. Удалите сохранённый конспект и повторите.' :
    error.name === 'TypeError' ? 'Не удалось загрузить файлы. Проверьте соединение и повторите.' : error.message || 'Сохранение недоступно.'})));
});
